public sealed class Rf129akVliwOperationIdAuthorityDecisionTests
{[Fact] public void PaperKeepsIssuedAttemptSeparate(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","3_Architectural_Overview_and_Frontend_Contract.md"));Assert.Contains("For `VliwOperationId`, default means no successful Stage-B issued attempt",p,StringComparison.Ordinal);Assert.Contains("the Stage-B issuer allocates an attempt",p,StringComparison.Ordinal);Assert.Contains("neither a request/token allocation nor a replay",p,StringComparison.Ordinal);Assert.Contains("No generic conversion",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
